//! Golden Matrices 3 & 4:
//! - Matrix 3: Priority operational logs (`Welcome to TiDB.` + `loaded config`, graceful
//!   shutdown sequence, `command dispatched failed`, `expensive_query` + `memory exceeds quota`,
//!   and `log`/`tracing`/`slog` bridges including `slog` `OwnedKVList` order reversal).
//! - Matrix 4: Offline `INFORMATION_SCHEMA.CLUSTER_LOG` parser verification (porting
//!   `pingcap/sysutil/search_log.go` `parseLogItem` / `readFirstValidLog`) over plain and `.gz`
//!   rotated files generated by [`RotatingFileSink`].

use std::fs;
use std::io::Read;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use flate2::read::GzDecoder;
use tidb_base::config::{Config, LogConfig, ZaplogFileLogConfig};
use tidb_base::errors;
use tidb_base::structured_log::{LogLevel, LogRecord, LogTarget};
use tidb_log::sink::{LogSink, MemorySink, RotatingFileSink};

static GLOBAL_TEST_LOCK: Mutex<()> = Mutex::new(());

fn assert_single_line(line: &[u8]) {
    assert_eq!(line.last(), Some(&b'\n'));
    let body = &line[..line.len() - 1];
    assert!(!body.contains(&b'\n'), "raw \\n inside line");
    assert!(!body.contains(&b'\r'), "raw \\r inside line");
}

/// Normalize leading `[YYYY/MM/DD HH:MM:SS.mmm ±HH:MM]` and `[file:line]` caller token so
/// Rust output can be compared whole-line byte-for-byte against Go v8.5.8 golden captures.
fn normalize_ts_and_caller(line: &str) -> String {
    let mut s = line.to_owned();
    // 1. Replace leading `[YYYY/MM/DD HH:MM:SS.mmm ±HH:MM]` with `[<TS>]`.
    if s.starts_with('[')
        && let Some(end) = s.find(']')
        && end == 31
    {
        s.replace_range(1..end, "<TS>");
    }
    // 2. Replace third bracket token `[file:line]` (after `[<TS>] [LEVEL] `) with `[<CALLER>]`.
    if let Some(lvl_end) = s.find("] [").and_then(|i| {
        let rest = &s[i + 3..];
        rest.find("] [").map(|j| i + 3 + j + 3)
    }) && let Some(caller_end) = s[lvl_end..].find(']')
    {
        let caller = &s[lvl_end..lvl_end + caller_end];
        if caller.contains(':') && !caller.contains(' ') {
            s.replace_range(lvl_end..lvl_end + caller_end, "<CALLER>");
        }
    }
    s
}

#[test]
fn matrix3_startup_banner_and_loaded_config_struct_order() {
    let _g = GLOBAL_TEST_LOCK.lock().unwrap();
    let sink = MemorySink::new();
    // Start at WARN level to prove print_tidb_info temporarily elevates to INFO and restores WARN!
    let cfg_log = LogConfig {
        level: "warn".to_owned(),
        format: "text".to_owned(),
        disable_timestamp: false,
        disable_error_verbose: true,
        ..LogConfig::default()
    };
    tidb_log::init_logger_with_sinks(&cfg_log, "", sink.clone(), None).unwrap();
    assert_eq!(tidb_log::get_level(), LogLevel::Warn);

    let cfg = Config::clone(&tidb_base::config::get_global_config());
    tidb_log::print_tidb_info(&cfg);
    // Level restored to WARN afterwards!
    assert_eq!(tidb_log::get_level(), LogLevel::Warn);

    let raw = sink.take();
    let text = String::from_utf8(raw).unwrap();
    let lines: Vec<&str> = text.lines().collect();
    assert_eq!(lines.len(), 2, "expected Welcome + loaded config:\n{text}");
    for l in &lines {
        assert_single_line(format!("{l}\n").as_bytes());
    }

    // 1. Whole-line normalized byte equality against Go v8.5.8 spec §4.1 `Welcome to TiDB.`
    // (with D1=A1 Release Version, empty GoVersion, and Rust Version).
    let expected_welcome = format!(
        "[<TS>] [INFO] [<CALLER>] [\"Welcome to TiDB.\"] \
         [\"Release Version\"={}] \
         [Edition={}] \
         [\"Git Commit Hash\"={}] \
         [\"Git Branch\"={}] \
         [\"UTC Build Time\"=\"{}\"] \
         [GoVersion=] \
         [\"Rust Version\"=\"{}\"] \
         [\"Race Enabled\"=false] \
         [\"Check Table Before Drop\"=false]",
        tidb_log::release_version(&cfg),
        tidb_log::edition(&cfg),
        tidb_log::TIDB_GIT_HASH,
        tidb_log::TIDB_GIT_BRANCH,
        tidb_log::TIDB_BUILD_TS,
        tidb_log::RUST_VERSION,
    );
    assert_eq!(normalize_ts_and_caller(lines[0]), expected_welcome);

    // 2. Whole-line normalized byte equality for `loaded config` (struct declaration order + exact
    // integer representation).
    let json_cfg = tidb_base::config::marshal_json(&cfg).unwrap();
    assert!(
        json_cfg.starts_with(r#"{"host":"0.0.0.0","advertise-address":"","port":4000,"#),
        "must preserve Go struct declaration order & exact int: {}",
        &json_cfg[..json_cfg.len().min(120)]
    );
    let mut expected_loaded_buf = Vec::new();
    tidb_log::encoder::text::safe_add_bytes(&mut expected_loaded_buf, json_cfg.as_bytes());
    let expected_loaded = format!(
        "[<TS>] [INFO] [<CALLER>] [\"loaded config\"] [config=\"{}\"]",
        String::from_utf8(expected_loaded_buf).unwrap()
    );
    assert_eq!(normalize_ts_and_caller(lines[1]), expected_loaded);

    // 3. GetTiDBInfo (-V / SELECT tidb_version()) exact 10-line layout.
    let ver_info = tidb_log::get_tidb_info(&cfg);
    assert_eq!(
        ver_info,
        format!(
            "Release Version: {}\n\
             Edition: {}\n\
             Git Commit Hash: {}\n\
             Git Branch: {}\n\
             UTC Build Time: {}\n\
             GoVersion: \n\
             Rust Version: {}\n\
             Race Enabled: false\n\
             Check Table Before Drop: false\n\
             Store: {}",
            tidb_log::release_version(&cfg),
            tidb_log::edition(&cfg),
            tidb_log::TIDB_GIT_HASH,
            tidb_log::TIDB_GIT_BRANCH,
            tidb_log::TIDB_BUILD_TS,
            tidb_log::RUST_VERSION,
            cfg.store,
        )
    );
}

#[test]
fn matrix3_general_log_and_bridges_including_slog_order() {
    let _g = GLOBAL_TEST_LOCK.lock().unwrap();
    let main_sink = MemorySink::new();
    let general_sink = MemorySink::new();
    let cfg = LogConfig {
        level: "debug".to_owned(),
        format: "text".to_owned(),
        disable_timestamp: false,
        disable_error_verbose: true,
        ..LogConfig::default()
    };
    tidb_log::init_logger_with_sinks(&cfg, "ks1", main_sink.clone(), Some(general_sink.clone()))
        .unwrap();
    tidb_log::set_level("warn").unwrap();

    // GeneralLogger logs at INFO even when global level is WARN, and routes to general_sink
    // with bound [keyspaceName=ks1].
    tidb_base::log_general!("GENERAL_LOG", "conn" => 42_u64, "sql" => "SELECT 1");
    assert!(main_sink.snapshot().is_empty());
    let g = String::from_utf8(general_sink.take()).unwrap();
    assert_single_line(g.as_bytes());
    assert_eq!(
        normalize_ts_and_caller(g.trim_end_matches('\n')),
        "[<TS>] [INFO] [<CALLER>] [GENERAL_LOG] [keyspaceName=ks1] [conn=42] [sql=\"SELECT 1\"]"
    );

    // log::warn! bridge
    log::warn!("from std log");
    let l = String::from_utf8(main_sink.take()).unwrap();
    assert_single_line(l.as_bytes());
    assert_eq!(
        normalize_ts_and_caller(l.trim_end_matches('\n')),
        "[<TS>] [WARN] [<CALLER>] [\"from std log\"] [keyspaceName=ks1]"
    );

    // tracing::warn! bridge & tracing::trace! filtered out even at DEBUG level
    tracing::warn!(conn = 7_u64, "from tracing");
    let t = String::from_utf8(main_sink.take()).unwrap();
    assert_single_line(t.as_bytes());
    assert_eq!(
        normalize_ts_and_caller(t.trim_end_matches('\n')),
        "[<TS>] [WARN] [<CALLER>] [\"from tracing\"] [keyspaceName=ks1] [conn=7]"
    );
    tidb_log::set_level("debug").unwrap();
    tracing::trace!("noisy hyper trace event");
    assert!(
        main_sink.take().is_empty(),
        "tracing::trace! must be filtered out even at DEBUG level"
    );

    // slog bridge: BOTH OwnedKVList AND call-site kv list must be reversed to preserve Go .With
    // and call-site declaration order (a=1, b=2, c=3, d=4)!
    let logger = slog_global::borrow_global()
        .new(slog::o!("a" => 1_i64))
        .new(slog::o!("b" => 2_i64));
    slog::warn!(logger, "from slog"; "c" => 3_i64, "d" => 4_i64);
    let sl = String::from_utf8(main_sink.take()).unwrap();
    assert_single_line(sl.as_bytes());
    assert_eq!(
        normalize_ts_and_caller(sl.trim_end_matches('\n')),
        "[<TS>] [WARN] [<CALLER>] [\"from slog\"] [keyspaceName=ks1] [a=1] [b=2] [c=3] [d=4]"
    );

    // tracing bridge dynamic level flip: a debug! call site first hit while level=INFO MUST NOT
    // freeze Interest::never() — flipping level to DEBUG via set_level must emit on the SAME site.
    fn hit_debug_site(seq: u32) {
        tracing::debug!(seq = seq, "dynamic debug probe");
    }
    tidb_log::set_level("info").unwrap();
    let _ = main_sink.take();
    hit_debug_site(1);
    assert!(
        main_sink.take().is_empty(),
        "debug! must be suppressed at INFO"
    );
    tidb_log::set_level("debug").unwrap();
    hit_debug_site(2);
    let dl = String::from_utf8(main_sink.take()).unwrap();
    assert_single_line(dl.as_bytes());
    assert_eq!(
        normalize_ts_and_caller(dl.trim_end_matches('\n')),
        "[<TS>] [DEBUG] [<CALLER>] [\"dynamic debug probe\"] [keyspaceName=ks1] [seq=2]"
    );
    tidb_log::set_level("info").unwrap();
}

#[test]
fn matrix3_replace_logger_json_and_fatal_dual_stack_and_timeout_in_hook() {
    let _g = GLOBAL_TEST_LOCK.lock().unwrap();
    let sink = MemorySink::new();
    let cfg = LogConfig {
        level: "info".to_owned(),
        format: "text".to_owned(),
        disable_timestamp: false,
        disable_error_verbose: true,
        ..LogConfig::default()
    };
    tidb_log::init_logger_with_sinks(&cfg, "", sink.clone(), None).unwrap();

    // 1. Fatal with explicit "stack" field still emits AddStacktrace(FatalLevel) (Go parity).
    tidb_base::log_fatal!("fatal dual stack", "stack" => "explicit-stack");
    let fl = String::from_utf8(sink.take()).unwrap();
    assert_single_line(fl.as_bytes());
    let norm_fl = normalize_ts_and_caller(fl.trim_end_matches('\n'));
    assert!(
        norm_fl.starts_with(
            "[<TS>] [FATAL] [<CALLER>] [\"fatal dual stack\"] [stack=explicit-stack] [stack=\""
        ),
        "expected both explicit stack and auto FatalLevel stack: {norm_fl}"
    );
    // Backtrace frames must strip `:col` and internal wrapper frames.
    assert!(
        !norm_fl.contains("std::backtrace::"),
        "internal std::backtrace frames must be stripped: {norm_fl}"
    );

    // 2. LockWithTimeoutSink: does NOT panic when inside panic hook (returns TimedOut Err).
    struct SlowSink;
    impl LogSink for SlowSink {
        fn write_entry(&self, _data: &[u8]) -> std::io::Result<()> {
            std::thread::sleep(Duration::from_millis(200));
            Ok(())
        }
        fn sync(&self) -> std::io::Result<()> {
            Ok(())
        }
    }
    let locked = Arc::new(tidb_log::LockWithTimeoutSink::new(
        Arc::new(SlowSink),
        Duration::from_millis(30),
    ));
    let holder = Arc::clone(&locked);
    let t = std::thread::spawn(move || {
        let _ = holder.write_entry(b"hold\n");
    });
    std::thread::sleep(Duration::from_millis(20));
    {
        let _hook_guard = tidb_base::panic_guard::enter_panic_hook().unwrap();
        let err = locked.write_entry(b"from hook\n").unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::TimedOut);
    }
    t.join().unwrap();

    // 3. replace_logger marshals exact Go pingcap/log.Config JSON fields (no slow-query-file /
    // general-log-file, includes development/disable-caller/disable-stacktrace/sampling/
    // error-output-path/timeout).
    let dir = std::env::temp_dir().join(format!(
        "tidb-log-replace-cfg-{}-{}",
        std::process::id(),
        Instant::now().elapsed().as_nanos()
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    let fpath = dir.join("tidb.log");
    let mut rcfg = LogConfig {
        level: "info".to_owned(),
        format: "text".to_owned(),
        disable_error_verbose: true,
        ..LogConfig::default()
    };
    rcfg.file.filename = fpath.to_string_lossy().into_owned();
    tidb_log::replace_logger(&rcfg).unwrap();
    tidb_log::sync().unwrap();
    let content = fs::read_to_string(&fpath).unwrap();
    let line = content.lines().next().unwrap();
    let expected_json = format!(
        "{{\"level\":\"info\",\"format\":\"text\",\"disable-timestamp\":false,\
         \"file\":{{\"filename\":\"{}\",\"max-size\":0,\"max-days\":0,\"max-backups\":0,\
         \"compression\":\"\",\"is-buffered\":false,\"buffer-size\":0,\"buffer-flush-interval\":0}},\
         \"development\":false,\"disable-caller\":false,\"disable-stacktrace\":false,\
         \"disable-error-verbose\":true,\"sampling\":null,\"error-output-path\":\"\",\"timeout\":0}}",
        fpath.to_string_lossy()
    );
    let mut escaped = Vec::new();
    tidb_log::encoder::text::safe_add_bytes(
        &mut escaped,
        format!("replaced global logger with config: {expected_json}").as_bytes(),
    );
    let expected_line = format!(
        "[<TS>] [INFO] [<CALLER>] [\"{}\"]",
        String::from_utf8(escaped).unwrap()
    );
    assert_eq!(normalize_ts_and_caller(line), expected_line);
    let _ = fs::remove_dir_all(&dir);
}

/// Offline port of `pingcap/sysutil@v1.0.1-0.20240311050922-ae81ee01f3a5/search_log.go`
/// `parseLogItem` (`:335-357`) verifying Matrix 4 (`INFORMATION_SCHEMA.CLUSTER_LOG`) compatibility.
fn parse_cluster_log_item(line: &str) -> Result<(&str, &str, &str), String> {
    const TS_LEN: usize = 30; // "2006/01/02 15:04:05.000 -07:00"
    let rest = line
        .strip_prefix('[')
        .ok_or_else(|| format!("missing leading '[': {line}"))?;
    let ts_end = rest
        .find(']')
        .ok_or_else(|| format!("missing timestamp ']': {line}"))?;
    let ts = &rest[..ts_end];
    if ts.len() != TS_LEN {
        return Err(format!("bad timestamp len {}: {ts:?}", ts.len()));
    }
    chrono::DateTime::parse_from_str(ts, "%Y/%m/%d %H:%M:%S%.3f %:z")
        .map_err(|e| format!("invalid timestamp {ts:?}: {e}"))?;

    let after_ts = rest[ts_end + 1..].trim_start();
    let after_lvl_open = after_ts
        .strip_prefix('[')
        .ok_or_else(|| format!("missing level '[': {line}"))?;
    let lvl_end = after_lvl_open
        .find(']')
        .ok_or_else(|| format!("missing level ']': {line}"))?;
    let lvl = &after_lvl_open[..lvl_end];
    match lvl.to_ascii_lowercase().as_str() {
        "debug" | "info" | "warn" | "trace" | "critical" | "error" => {}
        other => return Err(format!("CLUSTER_LOG unknown level {other:?}")),
    }
    let msg = after_lvl_open[lvl_end + 1..].trim();
    Ok((ts, lvl, msg))
}

#[test]
fn matrix4_cluster_log_parser_accepts_plain_and_gzip_rotated_files() {
    let _g = GLOBAL_TEST_LOCK.lock().unwrap();
    let dir = std::env::temp_dir().join(format!(
        "tidb-log-matrix4-{}-{}",
        std::process::id(),
        Instant::now().elapsed().as_nanos()
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();

    let log_path = dir.join("tidb.log");
    // Sibling slow log in the same directory MUST NOT be deleted by archive cleanup!
    let slow_log_path = dir.join("tidb-slow.log");
    fs::write(&slow_log_path, "# Time: 2026-11-27T01:00:00Z\n").unwrap();
    let fcfg = ZaplogFileLogConfig {
        filename: log_path.to_string_lossy().into_owned(),
        max_size: 1,
        max_days: 7,
        max_backups: 0,
        compression: "gzip".to_owned(),
        is_buffered: false,
        buffer_size: 0,
        buffer_flush_interval: 0,
    };
    // Small 512-byte threshold to force multiple rotations + gzip archives deterministically.
    let rotating = Arc::new(RotatingFileSink::new_with_max_bytes(&fcfg, 512, 0).unwrap());

    let lcfg = LogConfig {
        level: "debug".to_owned(),
        format: "text".to_owned(),
        disable_timestamp: false,
        disable_error_verbose: true,
        ..LogConfig::default()
    };
    tidb_log::init_logger_with_sinks(&lcfg, "", rotating.clone(), None).unwrap();

    let err = errors::new("multiline\nerror\r\ndetail");
    for i in 0..25_u64 {
        tidb_base::log_info!(
            "cluster log test entry",
            "seq" => i,
            "sql" => "SELECT\n  1,\n  2\nFROM t",
            "error" => &err,
        );
    }
    rotating.sync().unwrap();

    // Wait briefly for all background gzip threads to finish compressing archives (no uncompressed
    // rotated `tidb-*.log` left).
    let deadline = Instant::now() + Duration::from_secs(5);
    let mut gz_files = Vec::new();
    while Instant::now() < deadline {
        let entries: Vec<_> = fs::read_dir(&dir)
            .unwrap()
            .flatten()
            .map(|e| e.path())
            .collect();
        gz_files = entries
            .iter()
            .filter(|p| p.extension().is_some_and(|ext| ext == "gz"))
            .cloned()
            .collect();
        let pending_plain = entries.iter().any(|p| {
            p != &log_path
                && p.file_name()
                    .and_then(|s| s.to_str())
                    .is_some_and(|n| n.starts_with("tidb-") && n.ends_with(".log"))
        });
        if !gz_files.is_empty() && !pending_plain {
            break;
        }
        std::thread::sleep(Duration::from_millis(25));
    }
    assert!(
        !gz_files.is_empty(),
        "expected at least one .gz rotated archive"
    );

    // Verify every line in the active plain log file AND every .gz archive parses cleanly under
    // pingcap/sysutil's CLUSTER_LOG parser with zero cross-line contamination.
    let mut total_parsed = 0usize;
    let plain = fs::read_to_string(&log_path).unwrap();
    for line in plain.lines() {
        let (_, lvl, msg) = parse_cluster_log_item(line).unwrap();
        assert_eq!(lvl, "INFO");
        assert!(msg.contains("[\"cluster log test entry\"]"), "{msg}");
        total_parsed += 1;
    }

    for gz in &gz_files {
        let f = fs::File::open(gz).unwrap();
        let mut dec = GzDecoder::new(f);
        let mut content = String::new();
        dec.read_to_string(&mut content).unwrap();
        assert!(!content.is_empty(), "empty gz archive: {}", gz.display());
        for line in content.lines() {
            let (_, lvl, msg) = parse_cluster_log_item(line).unwrap();
            assert_eq!(lvl, "INFO");
            assert!(msg.contains("[\"cluster log test entry\"]"), "{msg}");
            total_parsed += 1;
        }
    }
    assert!(
        total_parsed >= 20,
        "expected >= 20 parsed entries across plain + gz, got {total_parsed}"
    );
    assert!(
        slow_log_path.exists(),
        "sibling tidb-slow.log must never be deleted by archive cleanup"
    );

    // Also verify structured logger trait directly emits valid single-line entries.
    let mem = MemorySink::new();
    tidb_log::init_logger_with_sinks(&lcfg, "", mem.clone(), None).unwrap();
    let logger = tidb_base::structured_log::logger();
    logger.log(&LogRecord {
        target: LogTarget::Main,
        level: LogLevel::Warn,
        logger_name: "",
        file: "test.rs",
        line: 10,
        msg: "memory exceeds quota",
        fields: &[],
    });
    let captured = String::from_utf8(mem.take()).unwrap();
    let (_, lvl, _) = parse_cluster_log_item(captured.trim_end_matches('\n')).unwrap();
    assert_eq!(lvl, "WARN");

    let _ = fs::remove_dir_all(&dir);
}
